pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {X_WALLET} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    X_WALLET c;

    function setUp() public {
        c = new X_WALLET(address(this));
    }

    function _run(uint256 _unlockTime) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        bool reverted;
        try c.Put{value: 0}(_unlockTime) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted);
    }

    function testFuzz_run(uint256 _unlockTime) public {
        _run(_unlockTime);
    }

    receive() external payable {}
}
